steps.code:
# Let's search for all songs to archive and collect their song_ids
archived_song_ids = []
for song in songs_to_archive:
    title = song['title']
    artist = song['artist']
    # Search for the song
    results = apis.spotify.search_songs(query=title, access_token=spotify_token)
    # Find exact match
    found = None
    for r in results:
        if r['title'].lower() == title.lower():
            # Check artist match
            for a in r['artists']:
                if a['name'].lower() == artist.lower():
                    found = r
                    break
            if found:
                break
    if found:
        archived_song_ids.append(found['song_id'])
        print(f"Found: {title} by {artist} -> song_id={found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal archived song IDs: {len(archived_song_ids)}")

