# Let's inspect the playlists' song_ids from the library response
for p in all_playlists:
    print(f"Playlist {p['playlist_id']} ({p['title']}): song_ids={p['song_ids']}")

# Check which songs are already in the "Old Songs" playlist (id 654) and add only missing ones
old_playlist = next(p for p in playlists if p["playlist_id"] == 654)
old_song_ids = set(old_playlist["song_ids"])

for song_id, title, artist in song_ids_to_archive:
    if song_id not in old_song_ids:
        result = apis.spotify.add_song_to_playlist(playlist_id=654, song_id=song_id, access_token=login_result["access_token"])
        print(f"Added song_id {song_id} ({title} by {artist}) to Old Songs: {result}")
    else:
        print(f"Song_id {song_id} already in Old Songs, skipping.")

# Verify all archived songs are removed from all playlists except "Old Songs" and present in "Old Songs"
# Re-fetch the playlist library to get current state
all_playlists = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=20)
    if not page:
        break
    all_playlists.extend(page)
    if len(page) < 20:
        break
    page_index += 1

archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
old_playlist = next(p for p in all_playlists if p["playlist_id"] == 654)
old_song_ids = set(old_playlist["song_ids"])

# Check missing songs in Old Songs
missing = archived_song_ids - old_song_ids
if missing:
    print(f"Missing songs in Old Songs: {missing}")
    for song_id in missing:
        result = apis.spotify.add_song_to_playlist(playlist_id=654, song_id=song_id, access_token=login_result["access_token"])
        print(f"Added missing song {song_id}: {result}")
else:
    print("All archived songs are present in Old Songs.")

# Check for any archived songs still in other playlists
for playlist in all_playlists:
    if playlist["playlist_id"] == 654:
        continue
    playlist_song_ids = set(playlist["song_ids"])
    overlap = playlist_song_ids & archived_song_ids
    if overlap:
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) still contains archived songs: {overlap}")
        for song_id in overlap:
            result = apis.spotify.remove_song_from_playlist(playlist_id=playlist["playlist_id"], song_id=song_id, access_token=login_result["access_token"])
            print(f"Removed song {song_id} from playlist {playlist['playlist_id']}: {result}")
    else:
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) is clean.")

