# Search for the first few songs to get their release dates
songs_to_search = todo_songs[:4]
for song in songs_to_search:
    result = apis.spotify.search_songs(query=song['title'], access_token=spotify_token, page_limit=20)
    # Find matching song by title and artists
    for item in result:
        if item['title'].lower() == song['title'].lower():
            # Check artists match
            item_artists = [a['name'] for a in item['artists']]
            if set(item_artists) == set(song['artists']):
                print(f"Found: {song['title']} -> release_date: {item['release_date']}")
                break
    else:
        print(f"Not found: {song['title']}")

# Search for the next batch of songs
songs_to_search = todo_songs[4:8]
for song in songs_to_search:
    result = apis.spotify.search_songs(query=song['title'], access_token=spotify_token, page_limit=20)
    found = False
