# Now we'll update the note content by replacing "RELEASED_AT TODO" with the correct month/year.
from datetime import datetime

# Build a mapping from song title to formatted month/year
release_month_year = {}
for title, date_str in release_dates.items():
    dt = datetime.fromisoformat(date_str)
    release_month_year[title] = dt.strftime("%m/%Y")

# Process the note content line by line
lines = note_content.split('\n')
new_lines = []
for line in lines:
    # Check if line contains "RELEASED_AT TODO"
    if "RELEASED_AT TODO" in line:
        # Extract the song title from the line. Format: "- Song Title BY Artist RELEASED_AT TODO"
        # We'll split by " BY " to get the title part
        parts = line.split(" BY ")
        if len(parts) == 2:
            title_part = parts[0].strip()
            # Remove leading "- " if present
            if title_part.startswith("- "):
                title_part = title_part[2:]
            # The title might have multiple words, but we can match against our mapping
            # We'll find the title in the mapping by checking if any key is a substring
            matched_title = None
            for t in release_month_year:
                if t.lower() in title_part.lower():
                    matched_title = t
                    break
            if matched_title:
                new_line = line.replace("RELEASED_AT TODO", f"RELEASED_AT {release_month_year[matched_title]}")
                new_lines.append(new_line)
            else:
                # If no match, keep as is (shouldn't happen)
                new_lines.append(line)
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print(new_content)

